namespace TensorStack.WPF { public static class Common { public static string GetRemainingTime(this Services.DownloadProgress p) => p.BytesSec > 0 ? System.TimeSpan.FromSeconds(System.Math.Max(0, p.TotalSize-p.TotalBytes)/p.BytesSec).ToString(@"hh\:mm\:ss") : ""; public static readonly string[] TextFileExtensions=[".txt",".md"]; public static readonly string[] ImageFileExtensions=[".png",".jpg",".jpeg",".bmp",".webp"]; public static readonly string[] VideoFileExtensions=[".mp4",".gif",".webm"]; public static readonly string[] AudioFileExtensions=[".wav",".mp3",".ogg",".flac"]; } }